/*
-----------------------------------------------
Blogger Template Style
Name:         Colorify
Version:      1.0.0 - Free
Author:       Templateify
Author Url:   https://www.templateify.com/
-----------------------------------------------*/

/*
<!-- Variable definitions -->
<Variable name="keycolor" description="Main Color" type="color" default="#FF3152" value="#FF3152"/>
<Group description="Theme Options">
    <Variable name="sidebar" description="Left Sidebar" type="length" default="0px" min="0px" max="1px" value="0px"/>
    <Variable name="fixedmenu" description="Fixed Menu" type="length" default="1px" min="0px" max="1px" value="1px"/>
    <Variable name="fixedsidebar" description="Fixed Sidebar" type="length" default="1px" min="0px" max="1px" value="1px"/>
</Group>
<Group description="Theme Widths">
    <Variable name="boxed" description="Boxed Mode" type="length" default="0px" min="0px" max="1px" value="0px"/>
    <Variable name="row.width" description="Container Width" type="length" default="970px" min="970px" max="1094px" value="970px"/>
    <Variable name="sidebar.width" description="Sidebar Width" type="length" default="300px" min="250px" max="336px" value="300px"/>
</Group>
<Group description="Theme Fonts">
    <Variable name="main.font" description="Site Font" type="font" family="Inter" default="normal 400 14px $(family)"  value="normal 400 14px $(family)"/>
    <Variable name="title.font" description="Title Font" type="font" family="Inter" default="normal 400 14px $(family)"  value="normal 400 14px $(family)"/>
    <Variable name="text.font" description="Text Font" type="font" family="Inter" default="normal 400 14px $(family)"  value="normal 400 14px $(family)"/>
</Group>
<Group description="Background">
    <Variable name="background.color" description="Body Background" type="color" default="#FAFAFA"  value="#FAFAFA"/>
    <Variable name="body.background" description="Background" type="background" color="$(background.color)" default="$(color) none repeat scroll top left" value="$(color) none repeat scroll top left"/>
    <Variable name="outer.bg" description="Outer Wrapper Background" type="color" default="#FFFFFF"  value="#FFFFFF"/>
</Group>
<Group description="Theme Colors">
    <Variable name="main.color" description="Theme Color" type="color" default="#FF3152" value="#FF3152"/>
    <Variable name="title.color" description="Title Color" type="color" default="#111111" value="#111111"/>
    <Variable name="title.hover.color" description="Title Hover Color" type="color" default="$(main.color)" value="#FF3152"/>
    <Variable name="meta.color" description="Meta Color" type="color" default="#959595" value="#959595"/>
    <Variable name="text.color" description="Text Color" type="color" default="#757575"  value="#757575"/>
</Group>
<Group description="Site Header" selector="#header-wrapper">
    <Variable name="header.bg" description="Header Background" type="color" default="#FFFFFF" value="#FFFFFF"/>
    <Variable name="header.color" description="Header Color" type="color" default="$(title.color)" value="#111111"/>
    <Variable name="header.hover.color" description="Header Hover Color" type="color" default="$(main.color)" value="#FF3152"/>
</Group>
<Group description="Sub Menu">
    <Variable name="submenu.bg" description="Sub Menu Background" type="color" default="#FFFFFF" value="#FFFFFF"/>
    <Variable name="submenu.color" description="Sub Menu Color" type="color" default="$(title.color)" value="#111111"/>
    <Variable name="submenu.hover.color" description="Sub Menu Hover Color" type="color" default="$(main.color)" value="#FF3152"/>
</Group>
<Group description="Mega Menu">
    <Variable name="megamenu.bg" description="Mega Menu Background" type="color" default="$(submenu.bg)" value="#FFFFFF"/>
    <Variable name="megamenu.color" description="Mega Menu Color" type="color" default="$(submenu.color)" value="#111111"/>
    <Variable name="megamenu.hover.color" description="MegaMenu Hover Color" type="color" default="$(main.color)" value="#FF3152"/>
</Group>
<Group description="Mobile Menu">
    <Variable name="mmenu.bg" description="Mobile Menu Background" type="color" default="#FFFFFF" value="#FFFFFF"/>
    <Variable name="mmenu.color" description="Mobile Menu Color" type="color" default="$(title.color)" value="#111111"/>
    <Variable name="mmenu.hover.color" description="Mobile Menu Hover Color" type="color" default="$(main.color)" value="#FF3152"/>
</Group>
<Group description="Header ADS" selector="#header-ads-wrap">
    <Variable name="headerad.onpost" description="Show on Post Page" type="length" default="1px" min="0px" max="1px" value="1px"/>
</Group>
<Group description="Theme Widgets" select="#sidebar">
    <Variable name="wtitle.color" description="Widget Title Color" type="color" default="$(title.color)" value="#111111"/>
</Group>
<Group description="Post Styles" select="#main">
    <Variable name="post.title.color" description="Post Title Color" type="color" default="$(title.color)" value="#111111"/>
    <Variable name="post.title.hover.color" description="Post Title Hover Color" type="color" default="$(title.hover.color)" value="#FF3152"/>
</Group>
<Group description="Post Page Styles" select="#main">
    <Variable name="post.text.color" description="Post Text Color" type="color" default="$(text.color)" value="#757575"/>
    <Variable name="itempost.title.size" description="Post Title Font Size" type="length" default="35px" min="20px" max="50px" value="35px"/>
    <Variable name="itempost.content.size" description="Post Text Font Size" type="length" default="14px" min="12px" max="20px" value="14px"/>
</Group>
<Group description="Post Page Options" select="#main">
    <Variable name="breadcrumb" description="Post Breadcrumbs" type="length" default="1px" min="0px" max="1px" value="1px"/>
    <Variable name="cmm.count" description="Comments Count" type="length" default="1px" min="0px" max="1px" value="1px"/>
    <Variable name="postnav" description="Post Navigation" type="length" default="1px" min="0px" max="1px" value="1px"/>
</Group>
<Group description="Footer ADS" selector="#footer-ads-wrap">
    <Variable name="footerad.onpost" description="Show on Post Page" type="length" default="1px" min="0px" max="1px" value="1px"/>
</Group>
<Group description="Theme Footer" selector="#footer-wrapper">
    <Variable name="footer.bg" description="Footer Background" type="color" default="#111111" value="#111111"/>
    <Variable name="footer.color" description="Footer Color" type="color" default="#FCFCFC" value="#FCFCFC"/>
    <Variable name="footer.text.color" description="Footer Text Color" type="color" default="#BABABA" value="#BABABA"/>
    <Variable name="footer.hover.color" description="Footer Hover Color" type="color" default="$(main.color)" value="#FF3152"/>
</Group>
<Group description="Footer Bar" selector=".footerbar">
    <Variable name="footerbar.bg" description="Footer Bar Background" type="color" default="#0C0C0C" value="#0C0C0C"/>
    <Variable name="footerbar.color" description="Footer Bar Color" type="color" default="#FCFCFC" value="#FCFCFC"/>
    <Variable name="footerbar.hover.color" description="Footer Bar Hover Color" type="color" default="$(main.color)" value="#FF3152"/>
</Group>
<Group description="Cookie Consent" selector="#colorify-free-cookie-ify">
    <Variable name="cookie.bg" description="Cookie Background" type="color" default="#FFFFFF" value="#FFFFFF"/>
    <Variable name="cookie.color" description="Cookie Text Color" type="color" default="$(text.color)" value="#757575"/>
</Group>
<Group description="Theme Buttons">
    <Variable name="button.bg" description="Button Background" type="color" default="$(main.color)" value="#FF3152"/>
    <Variable name="button.color" description="Button Color" type="color" default="#FFFFFF" value="#FFFFFF"/>
    <Variable name="button.hover.bg" description="Button Hover Background" type="color" default="#E52C4A" value="#E52C4A"/>
    <Variable name="button.hover.color" description="Button Hover Color" type="color" default="#FFFFFF" value="#FFFFFF"/>
</Group>
<Group description="Theme Fonts (Reset)">
    <!-- Site Font -->
    <Variable name="mainfont.medium" description="Main Font Medium" type="font" family="$(main.font.family)" default="normal 500 14px $(family)" value="normal 500 14px $(family)"/>
    <Variable name="mainfont.semibold" description="Main Font SemiBold" type="font" family="$(main.font.family)" default="normal 600 14px $(family)" value="normal 600 14px $(family)"/>
    <Variable name="mainfont.bold" description="Main Font Bold" type="font" family="$(main.font.family)" default="normal 700 14px $(family)" value="normal 700 14px $(family)"/>
    <Variable name="mainfont.italic" description="Main Font Italic" type="font" family="$(main.font.family)" default="italic 400 14px $(family)" value="italic 400 14px $(family)"/>
    <Variable name="mainfont.mediumitalic" description="Main Font Medium Italic" type="font" family="$(main.font.family)" default="italic 500 14px $(family)" value="italic 500 14px $(family)"/>
    <Variable name="mainfont.semibolditalic" description="Main Font SemiBold Italic" type="font" family="$(main.font.family)" default="italic 600 14px $(family)" value="italic 600 14px $(family)"/>
    <Variable name="mainfont.bolditalic" description="Main Font Bold Italic" type="font" family="$(main.font.family)" default="italic 700 14px $(family)" value="italic 700 14px $(family)"/>
    <!-- Site Font -->
    <Variable name="titlefont.medium" description="Title Font Medium" type="font" family="$(title.font.family)" default="normal 500 14px $(family)" value="normal 500 14px $(family)"/>
    <Variable name="titlefont.semibold" description="Title Font SemiBold" type="font" family="$(title.font.family)" default="normal 600 14px $(family)" value="normal 600 14px $(family)"/>
    <Variable name="titlefont.bold" description="Title Font Bold" type="font" family="$(title.font.family)" default="normal 700 14px $(family)" value="normal 700 14px $(family)"/>
    <Variable name="titlefont.italic" description="Title Font Italic" type="font" family="$(title.font.family)" default="italic 400 14px $(family)" value="italic 400 14px $(family)"/>
    <Variable name="titlefont.mediumitalic" description="Title Font Medium Italic" type="font" family="$(title.font.family)" default="italic 500 14px $(family)" value="italic 500 14px $(family)"/>
    <Variable name="titlefont.semibolditalic" description="Title Font SemiBold Italic" type="font" family="$(title.font.family)" default="italic 600 14px $(family)" value="italic 600 14px $(family)"/>
    <Variable name="titlefont.bolditalic" description="Title Font Bold Italic" type="font" family="$(title.font.family)" default="italic 700 14px $(family)" value="italic 700 14px $(family)"/>
    <!-- Site Font -->
    <Variable name="textfont.medium" description="Text Font Medium" type="font" family="$(text.font.family)" default="normal 500 14px $(family)" value="normal 500 14px $(family)"/>
    <Variable name="textfont.semibold" description="Text Font SemiBold" type="font" family="$(text.font.family)" default="normal 600 14px $(family)" value="normal 600 14px $(family)"/>
    <Variable name="textfont.bold" description="Text Font Bold" type="font" family="$(text.font.family)" default="normal 700 14px $(family)" value="normal 700 14px $(family)"/>
    <Variable name="textfont.italic" description="Text Font Italic" type="font" family="$(text.font.family)" default="italic 400 14px $(family)" value="italic 400 14px $(family)"/>
    <Variable name="textfont.mediumitalic" description="Text Font Medium Italic" type="font" family="$(text.font.family)" default="italic 500 14px $(family)" value="italic 500 14px $(family)"/>
    <Variable name="textfont.semibolditalic" description="Text Font SemiBold Italic" type="font" family="$(text.font.family)" default="italic 600 14px $(family)" value="italic 600 14px $(family)"/>
    <Variable name="textfont.bolditalic" description="Text Font Bold Italic" type="font" family="$(text.font.family)" default="italic 700 14px $(family)" value="italic 700 14px $(family)"/>
</Group>
<!-- Additional Variables -->
<Variable name="body.background.color" description="Comments Background" hideEditor="true" type="color" default="transparent"  value="transparent"/>
<Variable name="body.title.color" description="Comments Color" hideEditor="true" type="color" default="$(title.color)" value="#111111"/>
<Variable name="body.text.color" description="Comments Text Color" hideEditor="true" type="color" default="$(text.color)"  value="#757575"/>
<Variable name="body.link.color" description="Comments Link Color" hideEditor="true" type="color" default="$(main.color)"  value="#FF3152"/>
<Variable name="body.text.font" description="Comments Font 1" hideEditor="true" type="font" default="normal 400 15px Arial, sans-serif !important"  value="normal 400 15px Arial, sans-serif !important"/>
<Variable name="body.action.font.large" description="Comments Font 2" hideEditor="true" type="font" default="normal 700 14px Arial, sans-serif !important"  value="normal 700 14px Arial, sans-serif !important"/>
*/

