/*-- CSS Variables --*/
:root{
--body-font:'$(main.font.family)', Arial, sans-serif;
--title-font:'$(title.font.family)', Arial, sans-serif;
--meta-font:'$(main.font.family)', Arial, sans-serif;
--text-font:'$(text.font.family)', Arial, sans-serif;
--body-bg-color:$(background.color);
--body-bg:$(body.background);
--outer-bg:$(outer.bg);
--main-color:$(main.color);
--title-color:$(title.color);
--title-hover-color:$(title.hover.color);
--meta-color:$(meta.color);
--text-color:$(text.color);
--header-bg:$(header.bg);
--header-color:$(header.color);
--header-hover-color:$(header.hover.color);
--submenu-bg:$(submenu.bg);
--submenu-color:$(submenu.color);
--submenu-hover-color:$(submenu.hover.color);
--megamenu-bg:$(megamenu.bg);
--megamenu-color:$(megamenu.color);
--megamenu-hover-color:$(megamenu.hover.color);
--mobilemenu-bg:$(mmenu.bg);
--mobilemenu-color:$(mmenu.color);
--mobilemenu-hover-color:$(mmenu.hover.color);
--widget-title-color:$(wtitle.color);
--post-title-color:$(post.title.color);
--post-title-hover-color:$(post.title.hover.color);
--post-text-color:$(post.text.color);
--fbm-title-color:#FFFFFF;
--fbm-text-color:#EEEEEE;
--footer-bg:$(footer.bg);
--footer-color:$(footer.color);
--footer-hover-color:$(footer.hover.color);
--footer-text-color:$(footer.text.color);
--footerbar-bg:$(footerbar.bg);
--footerbar-color:$(footerbar.color);
--footerbar-hover-color:$(footerbar.hover.color);
--cookie-bg:$(cookie.bg);
--cookie-color:$(cookie.color);
--button-bg:$(button.bg);
--button-color:$(button.color);
--button-hover-bg:$(button.hover.bg);
--button-hover-color:$(button.hover.color);
--border-color:rgba(155,155,155,0.15);
--border-radius:6px;
--button-shadow:0 2px 6px rgba(0,0,0,0.15);
--avatar-shadow:0px 1px 4px rgba(0,0,0,0.15);
}
html.rtl{
--body-font:'Tajawal',Arial,sans-serif;
--title-font:'Tajawal',Arial,sans-serif;
--meta-font:'Tajawal',Arial,sans-serif;
--text-font:'Tajawal',Arial,sans-serif;
}

/*-- Reset CSS --*/
a,abbr,acronym,address,applet,b,big,blockquote,body,caption,center,cite,code,dd,del,dfn,div,dl,dt,em,fieldset,font,form,h1,h2,h3,h4,h5,h6,html,i,iframe,img,ins,kbd,label,legend,li,object,p,pre,q,s,samp,small,span,strike,strong,sub,sup,table,tbody,td,tfoot,th,thead,tr,tt,u,ul,var{padding:0;margin:0;border:0;outline:0;vertical-align:baseline;background:0 0;text-decoration:none}dl,ul{list-style-position:inside;list-style:none}ul li{list-style:none}caption{text-align:center}img{border:none;position:relative}a,a:visited{text-decoration:none}.clearfix{clear:both}.section,.widget,.widget ul{margin:0;padding:0}a{color:var(--main-color)}a img{border:0}abbr{text-decoration:none}.CSS_LIGHTBOX{z-index:999999!important}.CSS_LIGHTBOX_ATTRIBUTION_INDEX_CONTAINER .CSS_HCONT_CHILDREN_HOLDER > .CSS_LAYOUT_COMPONENT.CSS_HCONT_CHILD:first-child > .CSS_LAYOUT_COMPONENT{opacity:0}.separator a{clear:none!important;float:none!important;margin-left:0!important;margin-right:0!important}#Navbar1,#navbar-iframe,.widget-item-control,a.quickedit,.home-link,.feed-links{display:none!important}.center{display:table;margin:0 auto;position:relative}.widget > h2,.widget > h3{display:none}.widget iframe,.widget img{max-width:100%}button,input,select,textarea{font-family:var(--body-font);-webkit-appearance:none;-moz-appearance:none;appearance:none;outline:none;border-radius:0}

/*-- Style CSS --*/
*{box-sizing:border-box;word-break:break-word;word-wrap:break-word;text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased}
html{position:relative;margin:0}
body{position:relative;background:var(--body-bg);background-color:var(--body-bg-color);font-family:var(--body-font);font-size:14px;color:var(--text-color);font-weight:400;font-style:normal;line-height:1.4em;margin:0;padding:0}
.rtl{direction:rtl}
h1,h2,h3,h4,h5,h6{font-family:var(--title-font);font-weight:600}
a,input,button{transition:all .0s ease}
#outer-wrapper{position:relative;overflow:hidden;width:100%;max-width:100%;background-color:var(--outer-bg);margin:0 auto;padding:0}
.is-boxed #outer-wrapper{width:$(row.width + 60px);max-width:100%;box-shadow:0 0 20px rgba(0,0,0,0.1)}
.container{position:relative}
.row-x1{width:$(row.width)}
.flex-center{display:flex;justify-content:center}
#content-wrapper{position:relative;float:left;width:100%;overflow:hidden;padding:40px 0;margin:0}
.is-single #content-wrapper > .container{display:flex;justify-content:space-between}
.is-left #content-wrapper > .container{flex-direction:row-reverse}
.rtl .is-left #content-wrapper > .container{flex-direction:row}
.is-single #content-wrapper.no-sidebar > .container{justify-content:center}
.theiaStickySidebar:before,.theiaStickySidebar:after{content:'';display:table;clear:both}
.is-multiple #main-wrapper{position:relative;float:left;width:100%}
.is-single #main-wrapper{position:relative;width:calc(100% - $(sidebar.width + 40px))}
.is-single #content-wrapper.no-sidebar #main-wrapper{width:728px;max-width:100%}
#sidebar-wrapper{position:relative;width:$(sidebar.width)}
.btn{position:relative;border:0;box-shadow:var(--button-shadow)}
.entry-image-wrap,.author-avatar-wrap,.comments .avatar-image-container{display:block;position:relative;overflow:hidden;background-color:rgba(155,155,155,0.05);z-index:5;color:transparent!important}
.entry-thumb,.author-avatar{display:block;position:relative;width:100%;height:100%;background-size:cover;background-position:center center;background-repeat:no-repeat;z-index:1;opacity:0;transition:opacity .35s ease,filter 0 ease}
.author-avatar{background-size:100%;background-position:0 0}
.entry-thumb.lazy-ify,.author-avatar.lazy-ify{opacity:1}
.entry-image-wrap:hover .entry-thumb,.entry-inner:hover .entry-image-wrap .entry-thumb,.hero-post:hover .entry-image-wrap .entry-thumb{filter:brightness(1.03)}
.before-mask:before{content:'';position:absolute;left:0;right:0;bottom:0;height:70%;background-image:linear-gradient(to bottom,transparent,rgba(0,0,0,0.5));-webkit-backface-visibility:hidden;backface-visibility:hidden;z-index:2;opacity:1;margin:0;transition:opacity .25s ease}
.entry-image-wrap.is-video:after{position:absolute;content:'\f04b';top:50%;right:50%;background-color:rgba(0,0,0,0.5);width:38px;height:38px;font-family:'Font Awesome 5 Free';font-size:12px;color:#fff;font-weight:900;text-align:center;line-height:38px;z-index:5;transform:translate(50%,-50%);margin:0;box-shadow:var(--button-shadow);border-radius:50%;transition:background .17s ease}
.entry-image-wrap.is-video.c-ply:after{transform:translate(50%,-50%) scale(1.2)}
.entry-inner .entry-image-wrap.is-video:not(.c-ply):after{top:15px;right:15px;transform:translate(0%,0%)}
.rtl .entry-inner .entry-image-wrap.is-video:not(.c-ply):after{left:15px;right:unset}
.entry-image-wrap.is-video:hover:after,.entry-inner:hover .entry-image-wrap.is-video:after{background-color:var(--main-color)}
.entry-title{color:var(--post-title-color);font-weight:600;line-height:1.4em}
.entry-title a{display:block;color:var(--post-title-color)}
.entry-title a:hover{color:var(--post-title-hover-color)}
.entry-meta{font-family:var(--meta-font);font-size:12px;color:var(--meta-color);font-weight:400;margin:0}
.entry-meta .entry-author,.entry-meta .entry-time{display:flex}
.entry-meta .author-name{color:var(--main-color);font-weight:500}
.entry-meta .entry-tag{color:var(--main-color);text-transform:uppercase;font-weight:500}
.entry-meta.mi .entry-tag,.entry-meta.mi .author-name,.entry-meta .sp{margin:0 4px 0 0}
.rtl .entry-meta.mi .entry-tag,.rtl .entry-meta.mi .author-name,.rtl .entry-meta .sp{margin:0 0 0 4px}
.excerpt{font-family:var(--text-font);line-height:1.5em}
.entry-info{position:absolute;left:0;bottom:0;width:100%;background:linear-gradient(to bottom,transparent,rgba(0,0,0,0.65));overflow:hidden;z-index:5;display:flex;flex-direction:column;padding:15px}
.entry-info .entry-title{color:#fff;text-shadow:0 1px 2px rgba(0,0,0,0.1)}
.entry-info .entry-meta{color:#ccc}
.entry-info .entry-meta .author-name{color:#ddd}
.error-msg{display:flex;align-items:center;font-size:14px;color:var(--meta-color);padding:20px 0;font-weight:400}
.error-msg b{font-weight:600}
.loader{position:relative;width:100%;height:100%;overflow:hidden;display:flex;align-items:center;justify-content:center;margin:0}
.loader:after{content:'';display:block;width:30px;height:30px;box-sizing:border-box;margin:0;border:2px solid var(--border-color);border-left-color:var(--main-color);border-radius:100%;animation:spinner .65s infinite linear;transform-origin:center}
@-webkit-keyframes spinner {
0%{-webkit-transform:rotate(0deg);transform:rotate(0deg)}
to{-webkit-transform:rotate(1turn);transform:rotate(1turn)}
}
@keyframes spinner {
0%{-webkit-transform:rotate(0deg);transform:rotate(0deg)}
to{-webkit-transform:rotate(1turn);transform:rotate(1turn)}
}
